<script setup lang="ts">
import { ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { getTool } from '../registry'; import { useToolProcessing } from '../useToolProcessing'; import { decodeHex, encodeHex, type HexDelimiter } from './hex'
const { t }=useI18n(); const tool=getTool('soc-tools.hex'); const input=ref(''); const output=ref(''); const error=ref(''); const mode=ref<'encode'|'decode'>('encode'); const delimiter=ref<HexDelimiter>('none'); const uppercase=ref(false); const copied=ref(false)
function transform(){error.value='';copied.value=false;if(!input.value){output.value='';return}try{output.value=mode.value==='encode'?encodeHex(input.value,uppercase.value,delimiter.value):decodeHex(input.value)}catch(cause){output.value='';error.value=cause instanceof Error&&cause.message.includes('UTF-8')?t('tools.hex.invalidUtf8'):t('tools.hex.invalid')}}
const{inputBytes,isOverLimit,schedule}=useToolProcessing({input,output,error,maxInputBytes:tool.recommendedMaxInputBytes,process:transform})
function clear(){input.value='';output.value='';error.value='';copied.value=false} async function copyOutput(){if(output.value){await navigator.clipboard.writeText(output.value);copied.value=true}}
</script>
<template><section class="tool-page" aria-labelledby="tool-title"><header class="tool-heading"><span class="category">{{ t(`categories.${tool.category}`) }}</span><h1 id="tool-title">{{ t(tool.nameKey) }}</h1><p>{{ t(tool.descriptionKey) }}</p></header><div class="io-panel"><div class="terminal-titlebar"><span class="window-marks" aria-hidden="true"><i /><i /><i /></span><span>[ hex ]</span></div><div class="io-strip"><fieldset><legend>{{ t('common.operation') }}</legend><label class="radio-control"><input v-model="mode" type="radio" value="encode" @change="schedule"><span>{{ t('common.encode') }}</span></label><label class="radio-control"><input v-model="mode" type="radio" value="decode" @change="schedule"><span>{{ t('common.decode') }}</span></label></fieldset><span class="strip-divider" aria-hidden="true" /><label class="select-control">{{ t('tools.hex.delimiter') }}<select v-model="delimiter" :disabled="mode==='decode'" @change="schedule"><option value="none">{{ t('tools.hex.none') }}</option><option value="space">{{ t('tools.hex.space') }}</option><option value="0x">0x</option><option value="\x">\x</option></select></label><label class="check-control"><input v-model="uppercase" type="checkbox" :disabled="mode==='decode'" @change="schedule">{{ t('tools.hex.uppercase') }}</label><span class="byte-count">{{ inputBytes }} B</span><div class="strip-actions"><button class="icon-button" type="button" :disabled="!output" :aria-label="copied?t('common.copied'):t('common.copy')" @click="copyOutput"><svg aria-hidden="true" viewBox="0 0 24 24"><rect x="9" y="9" width="11" height="11" rx="2" /><path d="M15 9V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v7a2 2 0 0 0 2 2h3" /></svg></button><button class="icon-button" type="button" :aria-label="t('common.clear')" @click="clear"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M3 6h18M8 6V4h8v2m-9 0 1 14h8l1-14" /></svg></button></div></div><p v-if="isOverLimit" class="notice warning" role="alert">{{ t('common.inputTooLarge',{size:'1 MB'}) }}</p><div class="editor-grid"><div class="field"><label for="hex-input"><span>$</span> {{ t('common.input') }}</label><div class="terminal-editor input-editor"><span class="editor-prompt" aria-hidden="true">$</span><textarea id="hex-input" v-model="input" :class="{invalid:error}" :aria-invalid="Boolean(error)" :aria-describedby="error?'hex-error':undefined" :placeholder="t('tools.hex.placeholder')" spellcheck="false" @input="schedule" /></div></div><div class="field"><label for="hex-output"><span>&gt;</span> {{ t('common.output') }}</label><div class="terminal-editor"><span class="editor-prompt" aria-hidden="true">&gt;</span><textarea id="hex-output" :value="output" :placeholder="t('common.result')" readonly /></div></div></div><p v-if="error" id="hex-error" class="notice error" role="alert">{{ error }}</p></div></section></template>
